# TextArea TextArea ### Быстрый старт Быстрый старт ```tsx
import React from 'react';
import { TextArea } from '@salutejs/sdds-finai';
import { IconDownload } from '@salutejs/plasma-icons';

export function App() {
    return (
        <div>
            <TextArea
                label="Uncontrolled TextArea"
                defaultValue="Дефолтное значение"
                placeholder="Введите значение"
                contentRight={<IconDownload />}
                view="default"
            />
        </div>
    );
}
```

```tsx
import React, { useState } from 'react';
import { TextArea } from '@salutejs/sdds-finai';
import { IconDownload } from '@salutejs/plasma-icons';

export function App() {
    const [text, setText] = useState('Значение поля');

    return (
        <div>
            <TextArea
                value={text}
                onChange={(e: ChangeEvent<HTMLTextAreaElement>) => {
                    setText(e.target.value);
                }}
                label="Controlled TextArea"
                placeholder="Введите значение"
                contentRight={<IconDownload />}
                view="default"
            />
        </div>
    );
}
```

### Управление внешним видом Управление внешним видом Внешний вид компонента зависит от свойств  `appearance` ,  `view` ,  `size` . Доступные значения  `appearance` :  `default` ,  `viewMode` . `appearance="viewMode"`  — режим просмотра. ```tsx
import React from 'react';
import { TextArea } from '@salutejs/sdds-finai';
import { IconDownload } from '@salutejs/plasma-icons';

export function App() {
    return (
        <div style={{ display: 'flex', gap: '3rem', flexWrap: 'wrap'}}>
            <TextArea
                appearance="default"
                label="Appearance default"
                placeholder="Введите значение"
                contentRight={<IconDownload />}
            />
            <TextArea
                appearance="viewMode"
                label="Appearance viewMode"
                value="Значение только для просмотра"
                readOnly
                contentRight={<IconDownload />}
            />
        </div>
    );
}
```

